-- ---------------------------------------------------------------
-- cge:politica:1 · Três Poderes e eleições
-- ---------------------------------------------------------------
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:1', 0, 'mc', $q$No Brasil, os três Poderes são:$q$, $j${"opts":["Executivo, Legislativo e Judiciário","Presidente, Governador e Prefeito","Federal, Estadual e Municipal","Polícia, Exército e Justiça"],"a":0}$j$, $q$Executivo governa, Legislativo faz as leis e Judiciário julga. A divisão vem de Montesquieu e vale nos três níveis: União, estados e municípios.$q$, 1);
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:1', 1, 'mc', $q$Quem elabora e aprova as leis federais no Brasil?$q$, $j${"opts":["O Supremo Tribunal Federal","O Congresso Nacional (Câmara dos Deputados e Senado)","O presidente da República sozinho","Os governadores"],"a":1}$j$, $q$O Congresso é bicameral: 513 deputados federais e 81 senadores. O presidente sanciona ou veta as leis aprovadas.$q$, 1);
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:1', 2, 'mc', $q$Nas eleições para presidente, há segundo turno quando:$q$, $j${"opts":["Nenhum candidato alcança mais da metade dos votos válidos no primeiro turno","O candidato mais votado desiste","Há mais de dois candidatos","O TSE decide por sorteio"],"a":0}$j$, $q$É preciso maioria absoluta dos votos válidos (sem brancos e nulos). Se ninguém alcança, os dois mais votados disputam o segundo turno.$q$, 2);
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:1', 3, 'tf', $q$Julgue a afirmação sobre o voto$q$, $j${"stmt":"No Brasil o voto é obrigatório dos 18 aos 70 anos e facultativo para jovens de 16 e 17 anos, para maiores de 70 e para analfabetos.","a":true}$j$, $q$Verdadeiro: é o que diz a Constituição de 1988. As eleições são organizadas pela Justiça Eleitoral (TSE) com urna eletrônica desde 1996.$q$, 1);
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:1', 4, 'bank', $q$Complete a frase sobre os mandatos$q$, $j${"parts":["O presidente, os governadores, os prefeitos e os deputados têm mandato de "," anos; os senadores, de "," anos."],"a":["4","8"],"extra":["5","6"]}$j$, $q$Mandatos de 4 anos, com uma reeleição seguida para os cargos do Executivo; senadores têm 8 anos.$q$, 2);
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:1', 5, 'match', $q$Associe o cargo ou órgão ao Poder$q$, $j${"pairs":[["Presidente da República","Executivo"],["Senado Federal","Legislativo"],["Supremo Tribunal Federal","Judiciário"],["Câmara de Vereadores","Legislativo municipal"]]}$j$, $q$O STF tem 11 ministros e é a última instância do Judiciário; vereadores fazem as leis do município.$q$, 1);

-- cge:politica:2 · Direitos e Constituição
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:2', 0, 'mc', $q$A Constituição brasileira em vigor, chamada de "Constituição Cidadã", foi promulgada em:$q$, $j${"opts":["1964","1988","2002","1945"],"a":1}$j$, $q$5 de outubro de 1988, depois da ditadura militar; o apelido veio do presidente da Assembleia Constituinte, Ulysses Guimarães.$q$, 1);
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:2', 1, 'mc', $q$O Estatuto da Criança e do Adolescente (ECA), de 1990, garante:$q$, $j${"opts":["Direitos e proteção integral a pessoas de até 18 anos","Aposentadoria aos 60 anos","Voto obrigatório aos 14 anos","Trabalho infantil a partir dos 10 anos"],"a":0}$j$, $q$O ECA trata crianças (até 12 anos) e adolescentes (12 a 18) como sujeitos de direitos, com prioridade absoluta.$q$, 1);
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:2', 2, 'mc', $q$A Lei Maria da Penha (2006) trata de:$q$, $j${"opts":["Proteção do consumidor","Combate à violência doméstica e familiar contra a mulher","Cotas nas universidades","Direitos trabalhistas"],"a":1}$j$, $q$A lei leva o nome de Maria da Penha, farmacêutica cearense que ficou paraplégica após tentativas de assassinato pelo marido.$q$, 1);
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:2', 3, 'tf', $q$Julgue a afirmação sobre direitos sociais$q$, $j${"stmt":"Educação, saúde, alimentação, trabalho, moradia, transporte, lazer e segurança estão entre os direitos sociais previstos na Constituição de 1988.","a":true}$j$, $q$Verdadeiro: é a lista do artigo 6º, que inclui ainda previdência social, proteção à maternidade e à infância e assistência aos desamparados.$q$, 2);
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:2', 4, 'bank', $q$Complete a frase sobre a Constituição$q$, $j${"parts":["A Constituição de 1988 afirma que todo poder emana do ","; os pontos que não podem ser abolidos nem por emenda, como o voto direto e os direitos individuais, são as cláusulas ","."],"a":["povo","pétreas"],"extra":["Congresso","provisórias"]}$j$, $q$"Todo o poder emana do povo" (art. 1º). Cláusulas pétreas: federação, voto direto e secreto, separação dos Poderes e direitos e garantias individuais.$q$, 3);
select public.fj_seed_q('cge', 'cge:politica', 'cge:politica:2', 5, 'match', $q$Associe a lei ao que ela protege$q$, $j${"pairs":[["ECA","Crianças e adolescentes"],["Código de Defesa do Consumidor","Quem compra produtos e serviços"],["CLT","Trabalhadores com carteira assinada"],["Estatuto da Pessoa Idosa","Pessoas com 60 anos ou mais"]]}$j$, $q$ECA (1990), CDC (1990), CLT (1943) e Estatuto da Pessoa Idosa (2003).$q$, 2);

-- ---------------------------------------------------------------
-- cge:economia:1 · Inflação, juros e salário
-- ---------------------------------------------------------------
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:1', 0, 'mc', $q$Inflação é:$q$, $j${"opts":["O aumento generalizado e contínuo dos preços","A queda do dólar","O aumento do salário mínimo","O crescimento do PIB"],"a":0}$j$, $q$Com inflação, o mesmo dinheiro compra menos. Um produto só ficar mais caro não é inflação; ela é o aumento geral dos preços.$q$, 1);
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:1', 1, 'mc', $q$A taxa Selic, taxa básica de juros da economia brasileira, é definida pelo:$q$, $j${"opts":["Congresso Nacional","Comitê de Política Monetária (Copom) do Banco Central","IBGE","Supremo Tribunal Federal"],"a":1}$j$, $q$O Copom se reúne a cada 45 dias para decidir a Selic, que influencia todos os juros do país.$q$, 2);
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:1', 2, 'mc', $q$O índice oficial de inflação do Brasil, calculado pelo IBGE, é o:$q$, $j${"opts":["PIB","Selic","IPCA","IPTU"],"a":2}$j$, $q$IPCA: Índice Nacional de Preços ao Consumidor Amplo. É ele que o Banco Central usa como meta de inflação.$q$, 2);
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:1', 3, 'tf', $q$Julgue a afirmação sobre os juros$q$, $j${"stmt":"Quando o Banco Central aumenta a Selic, o crédito fica mais caro e o consumo tende a diminuir, o que ajuda a conter a inflação.","a":true}$j$, $q$Verdadeiro: juros altos freiam o consumo e a inflação, mas também desaceleram a economia. Por isso a decisão é sempre um equilíbrio.$q$, 2);
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:1', 4, 'bank', $q$Complete a frase sobre a economia$q$, $j${"parts":["O "," é a soma de tudo o que um país produz em um ano; o salário "," é o menor valor que um empregador pode pagar por mês a um trabalhador com carteira assinada."],"a":["PIB","mínimo"],"extra":["IPCA","médio"]}$j$, $q$PIB: Produto Interno Bruto. O salário mínimo é reajustado todo ano pelo governo federal.$q$, 1);
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:1', 5, 'match', $q$Associe o termo ao significado$q$, $j${"pairs":[["Juros compostos","Juros sobre juros, como no cartão de crédito"],["Pix","Transferência instantânea criada pelo Banco Central em 2020"],["Poupança","Aplicação simples com rendimento baixo e garantido"],["Deflação","Queda generalizada dos preços"]]}$j$, $q$Juros compostos fazem a dívida do cartão crescer rápido; o Pix é gratuito para pessoas físicas.$q$, 2);

-- cge:economia:2 · Impostos e orçamento
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:2', 0, 'mc', $q$Qual imposto é cobrado pelo município sobre casas e terrenos urbanos?$q$, $j${"opts":["IPVA","ICMS","IPTU","IR"],"a":2}$j$, $q$IPTU: Imposto Predial e Territorial Urbano, municipal. IPVA é sobre veículos (estadual) e IR é sobre a renda (federal).$q$, 1);
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:2', 1, 'mc', $q$O ICMS, imposto que incide sobre a circulação de mercadorias e que está embutido no preço de quase tudo o que compramos, é cobrado pelos:$q$, $j${"opts":["Municípios","Estados","União","Bancos"],"a":1}$j$, $q$O ICMS é estadual e é a maior fonte de receita dos estados; cada estado define as suas alíquotas.$q$, 2);
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:2', 2, 'mc', $q$O Imposto de Renda é:$q$, $j${"opts":["Um imposto federal sobre os ganhos de pessoas e empresas","Um imposto municipal sobre serviços","Uma taxa cobrada pelo cartório","Um imposto sobre carros"],"a":0}$j$, $q$O IR é federal, cobrado pela Receita Federal; quem ganha abaixo da faixa de isenção não paga.$q$, 1);
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:2', 3, 'tf', $q$Julgue a afirmação sobre os impostos$q$, $j${"stmt":"Impostos indiretos, como o ICMS, pesam mais sobre quem ganha menos, porque todos pagam o mesmo valor embutido no preço, independentemente da renda.","a":true}$j$, $q$Verdadeiro: é o que se chama de imposto regressivo. O Brasil cobra muito em consumo e pouco em renda e patrimônio.$q$, 3);
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:2', 4, 'bank', $q$Complete a frase sobre o orçamento público$q$, $j${"parts":["O orçamento do governo federal é definido na Lei Orçamentária Anual, aprovada pelo ","; a fiscalização dos gastos públicos é feita pelos Tribunais de ","."],"a":["Congresso","Contas"],"extra":["Banco Central","Justiça"]}$j$, $q$O Executivo propõe, o Congresso aprova e o Tribunal de Contas da União (TCU) e os tribunais estaduais fiscalizam.$q$, 3);
select public.fj_seed_q('cge', 'cge:economia', 'cge:economia:2', 5, 'match', $q$Associe o imposto ao que ele tributa$q$, $j${"pairs":[["IPTU","Imóveis urbanos (município)"],["IPVA","Veículos (estado)"],["Imposto de Renda","Ganhos de pessoas e empresas (União)"],["ICMS","Circulação de mercadorias (estado)"]]}$j$, $q$Município: IPTU e ISS. Estado: IPVA e ICMS. União: IR, IPI e contribuições.$q$, 2);

