select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:1', 0, 'mc', $q$A ONU (Organização das Nações Unidas) foi criada em 1945, logo após a Segunda Guerra Mundial, com o objetivo principal de:$q$, $j${"opts":["Manter a paz e a segurança internacionais","Organizar a Copa do Mundo","Controlar o preço do petróleo","Governar todos os países"],"a":0}$j$, $q$A ONU tem 193 países-membros e sede em Nova York; o Brasil é membro fundador.$q$, 1);
select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:1', 1, 'mc', $q$Os cinco membros permanentes do Conselho de Segurança da ONU, com poder de veto, são:$q$, $j${"opts":["Brasil, Alemanha, Japão, Índia e Canadá","Estados Unidos, Rússia, China, França e Reino Unido","Estados Unidos, México, Argentina, Chile e Peru","China, Japão, Coreia do Sul, Índia e Austrália"],"a":1}$j$, $q$São os vencedores da Segunda Guerra. O Brasil defende há décadas uma reforma do Conselho para ganhar assento permanente.$q$, 2);
select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:1', 2, 'mc', $q$O Mercosul é um bloco econômico formado em 1991 pelo Tratado de Assunção. Seus fundadores foram:$q$, $j${"opts":["Brasil, Argentina, Uruguai e Paraguai","Brasil, Chile, Peru e Colômbia","Brasil, México, Canadá e Estados Unidos","Brasil, Venezuela, Cuba e Bolívia"],"a":0}$j$, $q$Os quatro fundadores do Mercosul. A Venezuela entrou em 2012 e está suspensa desde 2016.$q$, 2);
select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:1', 3, 'tf', $q$Julgue a afirmação sobre a OMS$q$, $j${"stmt":"A OMS (Organização Mundial da Saúde) é a agência da ONU responsável pela saúde e foi ela que declarou a pandemia de covid-19 em março de 2020.","a":true}$j$, $q$Verdadeiro: a OMS, com sede em Genebra, declarou a pandemia em 11 de março de 2020.$q$, 1);
select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:1', 4, 'bank', $q$Complete a frase sobre o BRICS$q$, $j${"parts":["O BRICS reúne grandes economias emergentes: Brasil, Rússia, Índia, "," e África do Sul; em 2024 o grupo foi ampliado com novos membros, como Egito, Etiópia, Irã e Emirados Árabes ","."],"a":["China","Unidos"],"extra":["Canadá","Saudita"]}$j$, $q$A sigla vem das iniciais dos cinco países originais; a África do Sul entrou em 2011 e a expansão veio em 2024.$q$, 3);
select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:1', 5, 'match', $q$Associe a organização à sua função$q$, $j${"pairs":[["Unesco","Educação, ciência e cultura; títulos de patrimônio da humanidade"],["Unicef","Direitos das crianças"],["OMC","Regras do comércio internacional"],["Acnur","Proteção aos refugiados"]]}$j$, $q$Todas são ligadas à ONU: Unesco, Unicef, OMC (Organização Mundial do Comércio) e Acnur (Alto Comissariado para Refugiados).$q$, 2);

