select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:2', 0, 'mc', $q$Refugiado é a pessoa que:$q$, $j${"opts":["Viaja a turismo para outro país","Foge do seu país por perseguição, guerra ou violação grave de direitos","Muda de cidade para trabalhar","Nasceu em outro país"],"a":1}$j$, $q$A definição vem da Convenção de 1951 da ONU. O refugiado não pode ser devolvido ao país onde corre perigo.$q$, 1);
select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:2', 1, 'mc', $q$Em fevereiro de 2022, teve início a invasão em larga escala de qual país pela Rússia, provocando milhões de refugiados na Europa?$q$, $j${"opts":["Polônia","Ucrânia","Finlândia","Turquia"],"a":1}$j$, $q$A guerra na Ucrânia é o maior conflito na Europa desde a Segunda Guerra Mundial.$q$, 1);
select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:2', 2, 'mc', $q$Desde 2018, o Brasil recebe pela fronteira de Roraima um grande fluxo de migrantes que fogem da crise econômica e política de qual país?$q$, $j${"opts":["Colômbia","Venezuela","Peru","Haiti"],"a":1}$j$, $q$A Operação Acolhida, do governo federal, abriga e distribui os venezuelanos por outras cidades do Brasil.$q$, 2);
select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:2', 3, 'tf', $q$Julgue a afirmação sobre a OTAN$q$, $j${"stmt":"A OTAN (Organização do Tratado do Atlântico Norte) é uma aliança militar criada em 1949, liderada pelos Estados Unidos, da qual o Brasil não faz parte.","a":true}$j$, $q$Verdadeiro: a OTAN reúne Estados Unidos, Canadá e países europeus. O Brasil não é membro.$q$, 2);
select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:2', 4, 'bank', $q$Complete a frase sobre as migrações$q$, $j${"parts":["Quem sai do próprio país é ","; quem chega a um novo país para viver é ","."],"a":["emigrante","imigrante"],"extra":["turista","refugiado"]}$j$, $q$A mesma pessoa é emigrante no país de origem e imigrante no país de destino.$q$, 1);
select public.fj_seed_q('cge', 'cge:geopolitica', 'cge:geopolitica:2', 5, 'match', $q$Associe o conflito ou crise à região$q$, $j${"pairs":[["Guerra Rússia x Ucrânia","Leste Europeu"],["Conflito Israel x Hamas","Oriente Médio"],["Guerra civil no Sudão","Nordeste da África"],["Operação Acolhida (venezuelanos)","Norte do Brasil"]]}$j$, $q$Quatro crises humanitárias recentes e onde elas acontecem.$q$, 2);

-- ---------------------------------------------------------------
-- cge:ambiente:1 · Aquecimento global e acordos
-- ---------------------------------------------------------------
